import random

def random_string(count, start, end, letters=True, numbers=True):
    if count < 0:
        raise ValueError("count must be non-negative")

    char_set = ''
    if letters:
        char_set += string.ascii_letters[start:end]
    if numbers:
        char_set += string.digits[start:end]

    if not char_set:
        raise ValueError("No valid characters to choose from")

    return ''.join(random.choice(char_set) for _ in range(count))

