def to_identifier(text, quote, quote_on_non_identifier_char):
    if is_blank(text):
        return None
    start = next((i for i, char in enumerate(text) if not is_whitespace(char)), 0)
    end = next((i for i, char in enumerate(reversed(text)) if not is_whitespace(char)), len(text))
    if is_quoted(text, start, end):
        start += 1
        end -= 1
        quote = True
    elif quote_on_non_identifier_char and not quote:
        c = text[start]
        if not is_letter(c) and c != '_':
            quote = True
        else:
            for i in range(start + 1, end):
                c = text[i]
                if not is_letter_or_digit(c) and c != '_':
                    quote = True
                    break
    return Identifier(text[start:end], quote)

