def build_callback_registry(options, service_registry, entity_bindings):
    if not options.are_jpa_callbacks_enabled():
        return EmptyCallbackRegistryImpl()

    bean_registry = service_registry.get_service(ManagedBeanRegistry)
    registry_builder = CallbackRegistryImpl.Builder()
    entity_classes: Set[type] = set()

    for persistent_class in entity_bindings:
        if persistent_class.class_name is not None:
            entity_class = persistent_class.mapped_class
            if not entity_classes.add(entity_class):
                if log.isDebugEnabled():
                    log.debug(f"Class [{entity_class.__name__}] already has callbacks registered; assuming this means the class was mapped twice (using hbm.xml entity-name support) - skipping subsequent registrations to avoid duplicates")
            else:
                register_all_callbacks(persistent_class, registry_builder, entity_class, bean_registry)

    return registry_builder.build()

def register_all_callbacks(persistent_class, registry_builder, entity_class, bean_registry):
    registry_builder.registerCallbacks(entity_class, build_callbacks(persistent_class.callback_definitions, bean_registry))

    for property_ in persistent_class.declared_properties:
        registry_builder.registerCallbacks(entity_class, build_callbacks(property_.callback_definitions, bean_registry))

