def get_forced_code_set(hints: Optional[Dict[Any, Any]]) -> int:
    if hints is None or "FORCE_CODE_SET" not in hints:
        return -1

    hint_val = str(hints["FORCE_CODE_나SET"])
    mapping = {"A": CODE_CODE_A, "B": CODE_CODE_B, "C": CODE_CODE_C}

    if hint_val not in mapping:
        raise ValueError(f"Unsupported code set hint: {hint_val}")
    return mapping[hint_val]

def validate_content_for_code_set(char_code: int, forced_code_set: int):
    if forced_code_set == CODE_CODE_A:
        if 95 < char_code <= 127:
            raise ValueError(f"Bad character in input for forced code set A: ASCII value={char_code}")
    elif forced_code_set == CODE_CODE_B:
        if char_code <= 32:
            raise ValueError(f"Bad character in input for forced code set B: ASCII value={char_code}")
    elif forced_code_set == CODE_CODE_C:
        if char_code < 48 or (57 < char_code <= 127) or char_code in [ESCAPE_FNC_2, ESCAPE_FNC_3, ESCAPE_FNC_4]:
            raise ValueError(f"Bad character in input for forced code set C: ASCII value={char_code}")

def check_content_validity(contents: str, forced_code_set: int):
    for char in contents:
        c_code = ord(char)
        if c_code > 127 and c_code not in [ESCAPE_FNC_1, ESCAPE_FNC_2, ESCAPE_FNC_3, ESCAPE_FNC_4]:
            raise ValueError(f"Bad character in input: ASCII value={c_code}")
        validate_content_for_code_set(c_code, forced_code_set)

def check(contents: str, hints: Optional[Dict[Any, Any]]) -> int:
    length = len(contents)
    if length < 1 or length > 80:
        raise ValueError(f"Contents length should be between _1_ and 80 characters, but got {length}")

    forced_code_set = get_forced_code_set(hints)
    check_content_validity(contents, forced_code_set)
    return forced_code_set

