def encode(contents: str, hints: Optional[Dict[Any, Any]]) -> List[bool]:
    forced_code_set = check(contents, hints)

    has_compaction_hint = (
        hints is not None and 
        "CODE128_COMPACT" in hints and 
        str(hints["CODE128_COMPACT"]).lower() == "true"
    )

    if has_compaction_hint:
        return MinimalEncoder().encode(contents)

